<?php
session_start(); if(!isset($_SESSION['divisi'])||$_SESSION['divisi']!=='akunting'){header('Location: ../index.php');exit;} require_once '../config/database.php';
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $aksi=$_POST['aksi']??'';
 try{
  if($aksi==='tambah'){ $nama=trim($_POST['nama_pekerjaan']??'');$harga=(float)($_POST['harga_per_satuan']??0);if($nama===''||$harga<=0)throw new Exception('Nama pekerjaan dan harga wajib diisi.');$st=$pdo->prepare("INSERT INTO master_tarif(nama_pekerjaan,harga_per_satuan,tipe_tarif,status_aktif) VALUES(?,?, 'berat', true)");$st->execute([$nama,$harga]);$msg='Tarif berhasil ditambahkan.'; }
  elseif($aksi==='ubah'){ $id=(int)$_POST['id'];$nama=trim($_POST['nama_pekerjaan']??'');$harga=(float)$_POST['harga_per_satuan'];$status=isset($_POST['status_aktif']);$st=$pdo->prepare("UPDATE master_tarif SET nama_pekerjaan=?,harga_per_satuan=?,status_aktif=? WHERE id=?");$st->execute([$nama,$harga,$status,$id]);$msg='Tarif berhasil diperbarui.'; }
 }catch(Throwable $e){$err=$e->getMessage();}
}
$rows=$pdo->query("SELECT id,nama_pekerjaan,harga_per_satuan,tipe_tarif,status_aktif,created_at FROM master_tarif ORDER BY status_aktif DESC,nama_pekerjaan")->fetchAll();
function rp($v){return 'Rp '.number_format((float)$v,0,',','.');}
?>
