a/Satuan</th><th>Tipe</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php $no=1;foreach($rows as $r): ?><tr><td><?=$no++?></td><td><?=htmlspecialchars($r['nama_pekerjaan'])?></td><td><?=rp($r['harga_per_satuan'])?></td><td><?=htmlspecialchars($r['tipe_tarif'])?></td><td><span class="badge <?=$r['status_aktif']?'bg-success':'bg-secondary'?>"><?=$r['status_aktif']?'Aktif':'Nonaktif'?></span></td><td><button class="btn btn-sm btn-outline-success" data-bs-toggle="modal" data-bs-target="#edit<?=$r['id']?>">Edit</button></td></tr><div class="modal fade" id="edit<?=$r['id']?>" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title">Edit Tarif</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="aksi" value="ubah"><input type="hidden" name="id" value="<?=$r['id']?>"><label class="form-label">Nama Pekerjaan</label><input class="form-control mb-3" name="nama_pekerjaan" value="<?=htmlspecialchars($r['nama_pekerjaan'])?>" required><label class="form-label">Harga per Satuan</label><input type="number" min="0" step="0.01" class="form-control mb-3" name="harga_per_satuan" value="<?=$r['harga_per_satuan']?>" required><div class="form-check"><input class="form-check-input" type="checkbox" name="status_aktif" id="s<?=$r['id']?>" <?=$r['status_aktif']?'checked':''?>><label class="form-check-label" for="s<?=$r['id']?>">Tarif aktif</label></div></div><div class="modal-footer"><button class="btn btn-success">Simpan</button></div></form></div></div></div><?php endforeach;if(!$rows): ?><tr><td colspan="6" class="text-center text-muted py-4">Belum ada tarif.</td></tr><?php endif;?></tbody></table></div></div></div></main></div></div><div class="modal fade" id="modalTambah" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><form method="post"><div class="modal-header"><h5 class="modal-title">Tambah Tarif</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="aksi" value="tambah"><label class="form-label">Nama Pekerjaan</label><input class="form-control mb-3" name="nama_pekerjaan" required><label class="form-label">Harga per Satuan</label><input type="number" min="0" step="0.01" class="form-control" name="harga_per_satuan" required><small class="text-muted">Tipe tarif otomatis: berat.</small></div><div class="modal-footer"><button class="btn btn-success">Simpan</button></div></form></div></div></div><script src="../assets/js/bootstrap.bundle.min.js"></script></body></html>
